"use strict";(self.webpackChunkmystic_auth_docs=self.webpackChunkmystic_auth_docs||[]).push([["8293"],{1274(e,t,n){n.r(t),n.d(t,{metadata:()=>o,default:()=>h,frontMatter:()=>r,contentTitle:()=>a,toc:()=>c,assets:()=>l});var o=JSON.parse('{"id":"mystic_auth/project-story/README","title":"Project Story","description":"---","source":"@site/docs/mystic_auth/project-story/README.md","sourceDirName":"mystic_auth/project-story","slug":"/mystic_auth/project-story/","permalink":"/mystic-auth-docs/docs/mystic_auth/project-story/","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{},"sidebar":"tutorialSidebar","previous":{"title":"Legal","permalink":"/mystic-auth-docs/docs/mystic_auth/legal/overview"},"next":{"title":"Structure: Then and Now","permalink":"/mystic-auth-docs/docs/mystic_auth/project-story/structure-then-and-now"}}'),s=n(4848),i=n(8453);let r={},a="Project Story",l={},c=[{value:"Where this started",id:"where-this-started",level:2},{value:"How it evolved",id:"how-it-evolved",level:2},{value:"Architecture evolution",id:"architecture-evolution",level:2},{value:"The tools that built it",id:"the-tools-that-built-it",level:2},{value:"Why it is a template now",id:"why-it-is-a-template-now",level:2}];function d(e){let t={a:"a",blockquote:"blockquote",code:"code",h1:"h1",h2:"h2",header:"header",hr:"hr",li:"li",p:"p",pre:"pre",ul:"ul",...(0,i.R)(),...e.components};return(0,s.jsxs)(s.Fragment,{children:[(0,s.jsx)(t.header,{children:(0,s.jsx)(t.h1,{id:"project-story",children:"Project Story"})}),"\n",(0,s.jsx)(t.hr,{}),"\n",(0,s.jsx)(t.h2,{id:"where-this-started",children:"Where this started"}),"\n",(0,s.jsx)(t.p,{children:"This project started because I got tired of rebuilding the same authentication and authorization pieces for different startup take-home assignments."}),"\n",(0,s.jsx)(t.p,{children:"During 2025, while applying to startups, many take-home projects needed similar foundations with slightly different expectations: one needed email/password authentication, another needed OAuth2, another wanted RBAC. Each time, the actual product logic was slowed down because much time went into rebuilding the same authentication foundation."}),"\n",(0,s.jsx)(t.p,{children:"The original idea was simple:"}),"\n",(0,s.jsxs)(t.blockquote,{children:["\n",(0,s.jsx)(t.p,{children:"Build auth + OAuth2 + a basic authorization layer once, then reuse it."}),"\n"]}),"\n",(0,s.jsx)(t.p,{children:"I assumed this would take a week or two. Almost a year later, after working on it on and off between a master's programme and long gaps where I didn't touch it at all, it's still going. It grew into a full template with PBAC, audit logging, CI/CD, and a real test suite instead of the small module I set out to build."}),"\n",(0,s.jsx)(t.p,{children:"Authentication looks small from the outside: a login endpoint, a logout endpoint, maybe a token. It quickly becomes its own engineering domain. The project expanded into understanding and implementing:"}),"\n",(0,s.jsxs)(t.ul,{children:["\n",(0,s.jsx)(t.li,{children:"refresh token rotation and reuse detection,"}),"\n",(0,s.jsx)(t.li,{children:"session storage decisions,"}),"\n",(0,s.jsx)(t.li,{children:"Redis-based session and token management,"}),"\n",(0,s.jsx)(t.li,{children:"rate limiting,"}),"\n",(0,s.jsx)(t.li,{children:"brute-force protection,"}),"\n",(0,s.jsx)(t.li,{children:"cookie security,"}),"\n",(0,s.jsx)(t.li,{children:"OAuth2 PKCE flows,"}),"\n",(0,s.jsx)(t.li,{children:"background email delivery through asynchronous workers,"}),"\n",(0,s.jsx)(t.li,{children:"database migrations,"}),"\n",(0,s.jsx)(t.li,{children:"CI validation,"}),"\n",(0,s.jsx)(t.li,{children:"frontend authorization handling."}),"\n"]}),"\n",(0,s.jsx)(t.p,{children:"What started as a shortcut for future projects became a project of its own."}),"\n",(0,s.jsx)(t.hr,{}),"\n",(0,s.jsx)(t.h2,{id:"how-it-evolved",children:"How it evolved"}),"\n",(0,s.jsxs)(t.p,{children:["The commit-by-commit log of what actually happened, from the first commit on 18 August, 2025\nthrough today, got long enough to outgrow this page: see ",(0,s.jsx)(t.a,{href:"/mystic-auth-docs/docs/mystic_auth/project-story/timeline",children:"How It Evolved"})," for the\nfull timeline and milestone diagram."]}),"\n",(0,s.jsx)(t.hr,{}),"\n",(0,s.jsx)(t.h2,{id:"architecture-evolution",children:"Architecture evolution"}),"\n",(0,s.jsx)(t.p,{children:"The architecture wasn't designed perfectly from the beginning. Early on, I explored different structures, including more traditional MVC-style approaches and layouts copied from examples found online."}),"\n",(0,s.jsx)(t.p,{children:"As the project grew, a problem became obvious: authentication flows aren't isolated files. A single feature could involve API routes, schemas, services, handlers, database models, frontend pages, API clients, state management, and tests. When these pieces were spread across unrelated folders, debugging got harder, because understanding one flow meant jumping across many locations."}),"\n",(0,s.jsx)(t.p,{children:"So instead of organizing only by technical type:"}),"\n",(0,s.jsx)(t.pre,{children:(0,s.jsx)(t.code,{className:"language-text",children:"controllers/\nservices/\nmodels/\nschemas/\n"})}),"\n",(0,s.jsx)(t.p,{children:"I moved toward grouping related behavior together, by feature instead of by layer."}),"\n",(0,s.jsx)(t.p,{children:"This was the structure right before the PBAC and Claude Code sprint, in the last commit of the manual, ChatGPT-assisted era on 14 April, 2026:"}),"\n",(0,s.jsx)(t.pre,{children:(0,s.jsx)(t.code,{className:"language-text",children:"backend/\n  app/\n    api/\n      auth_routes/\n      user_routes/\n\n    auth/\n      current_user/\n      login/\n      logout/\n      logout_all/\n      oauth2/\n      password_logic/\n      password_reset_confirm/\n      password_reset_request/\n      refresh_token_logic/\n      security/\n      signup/\n      token_logic/\n      verify_account/\n\n    core/\n    database/\n    logging/\n    redis/\n    scripts/\n    taskiq_tasks/\n    user_crud/\n    user_table/\n\nfrontend/\n  src/\n    api/\n\n    auth/\n      current_user/\n      login/\n      logout/\n      logout_all/\n      oauth2/\n      password_reset_confirm/\n      password_reset_request/\n      signup/\n      verify_account/\n\n    core/\n    dashboard/\n    store/\n"})}),"\n",(0,s.jsx)(t.p,{children:"Grouping code around business flows, instead of forcing every feature across separate technical layers, made changes easier: everything needed for a feature lived close together. Changing login behavior meant working mostly inside the authentication area, not hunting across unrelated controller, service, and model folders."}),"\n",(0,s.jsxs)(t.p,{children:["This wasn't chosen because it's the only \"correct\" architecture. It was chosen because, for this project's size and workflow, it made the system easier to understand, debug, and extend. That decision mattered even more later, when a single commit on 14 July, 2026 moved the project from role-based access to PBAC, the biggest change the codebase went through: see ",(0,s.jsx)(t.a,{href:"/mystic-auth-docs/docs/mystic_auth/project-story/timeline#14-july-2026",children:"How It Evolved"})," for that commit and everything after it, day by day."]}),"\n",(0,s.jsx)(t.hr,{}),"\n",(0,s.jsx)(t.h2,{id:"the-tools-that-built-it",children:"The tools that built it"}),"\n",(0,s.jsxs)(t.p,{children:["Two very different workflows built this project: a manual ChatGPT + VSCode loop for most of it, then an agentic coding loop with Claude Code from July 2026 on and Codex joining from the commit of 28 July, 2026 (Yeah, I hit my Claude Code weekly limit) for a few days until I exhausted my free Codex credits. The workflow details and diagram live in ",(0,s.jsx)(t.a,{href:"/mystic-auth-docs/docs/mystic_auth/project-story/tools",children:"The Tools That Built It"}),"."]}),"\n",(0,s.jsx)(t.hr,{}),"\n",(0,s.jsx)(t.h2,{id:"why-it-is-a-template-now",children:"Why it is a template now"}),"\n",(0,s.jsx)(t.p,{children:"Somewhere during the infrastructure and security work, this stopped being just a personal shortcut. The problems solved here, authentication, sessions, permissions, security controls, audit trails, email workflows, and testing, come up in almost every application with users."}),"\n",(0,s.jsx)(t.p,{children:"The point of this template isn't just saving development time. It's a starting point with documented architectural decisions, tested authentication flows, reusable authorization patterns, and security considerations already handled, so a new project can start from a stronger baseline and focus on the actual product being built."}),"\n",(0,s.jsxs)(t.p,{children:["See ",(0,s.jsx)(t.a,{href:"/mystic-auth-docs/docs/mystic_auth/template-usage/overview",children:"Using This Repository as a Template"})," for how to adapt it."]}),"\n",(0,s.jsx)(t.hr,{})]})}function h(e={}){let{wrapper:t}={...(0,i.R)(),...e.components};return t?(0,s.jsx)(t,{...e,children:(0,s.jsx)(d,{...e})}):d(e)}},8453(e,t,n){n.d(t,{R:()=>r,x:()=>a});var o=n(6540);let s={},i=o.createContext(s);function r(e){let t=o.useContext(i);return o.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function a(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:r(e.components),o.createElement(i.Provider,{value:t},e.children)}}}]);